from pathlib import Path
import json,html
root=Path(__file__).resolve().parent.parent
report=json.loads((root/'docs/micro-immuno-review/verification-results.json').read_text())
items=[]
for r in report['results']:
 if r.get('screenshot'):
  items.append({'slug':r['slug'],'width':r['width'],'font':'system' if r['font']=='system-ui' else 'fallback' if r['font']=='sans-serif' else 'noto','kind':r['kind'],'id':r['id'],'file':r['screenshot'],'title':('實驗室｜' if r['kind']=='lab' else '知識節點｜')+r['id']})
for slug in ['micro-bacteria-review','immuno-concepts-review']:
 for width in [1280,390]:
  for mode in ['warm','cool','os-dark']:
   items.append({'slug':slug,'width':width,'font':'system','kind':'page','id':mode,'file':f'{slug}-{width}-{mode}-page.png','title':{'warm':'完整頁面｜預設色系','cool':'完整頁面｜冷色樣式（測試設定）','os-dark':'完整頁面｜系統深色偏好（kit 維持淺色）'}[mode]})
 items.append({'slug':slug,'width':390,'font':'system','kind':'page','id':'reduced-motion','file':f'{slug}-390-reduced-motion.png','title':'390｜減少動態'})
# Fast diagnostic results intentionally lack screenshot names; regenerate from filenames if needed.
if not any(x['kind']!='page' for x in items):
 for slug,node_count,states in [('micro-bacteria-review',6,['unstained','crystal-violet','iodine','decolorize','safranin']),('immuno-concepts-review',8,['primary','secondary'])]:
  for width in [1280,390]:
   for font in ['system','noto']:
    for kind,ids in [('lab',states),('node',[f'{i:02d}' for i in range(1,node_count+1)])]:
     for id in ids:items.append({'slug':slug,'width':width,'font':font,'kind':kind,'id':id,'file':f'{slug}-{width}-{font}-{kind}-{id}.png','title':('實驗室｜' if kind=='lab' else '知識節點｜')+id})
head='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>115-MI 微免總複習｜教師畫面檢視</title><style>
:root{font:16px/1.6 system-ui,sans-serif;color:#23364a;background:#f5f7fa}*{box-sizing:border-box}body{margin:0}main{max-width:1160px;margin:auto;padding:28px 20px}h1{font-size:30px;margin:0 0 8px}h2{font-size:20px;margin:0}header{margin-bottom:24px}.lead{max-width:850px;color:#506074}nav{display:flex;gap:12px;flex-wrap:wrap}a{color:#1d5792;text-underline-offset:3px}nav a{padding:10px 16px;border:1px solid #c6d5e2;border-radius:10px;background:#fff}.controls{display:flex;flex-wrap:wrap;gap:14px;position:sticky;top:0;background:#f5f7faf5;padding:14px 0;z-index:2;border-bottom:1px solid #d5e0e8}label{display:flex;align-items:center;gap:8px}select{font:inherit;border:1px solid #b9cbd9;padding:8px;border-radius:8px;background:white;color:inherit}.status{color:#64748b;font-size:14px}#grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:20px}article{border:1px solid #cfdae3;border-radius:14px;background:white;overflow:hidden}article .cap{padding:14px;border-bottom:1px solid #e5ebf0}.cap small{display:block;color:#64748b}.image{max-height:780px;overflow:auto;padding:12px;background:#eef2f6}.image img{display:block;width:100%;height:auto;background:white}.mobile .image img{max-width:390px;margin:auto}.tools{padding:10px 14px;font-size:14px}footer{margin:32px 0;color:#64748b}.notice{padding:12px 16px;background:#edf3f8;border-left:4px solid #6b879f;border-radius:5px}@media(max-width:760px){main{padding:20px 12px}h1{font-size:24px}#grid{grid-template-columns:1fr}.controls{position:static}label{flex-wrap:wrap}.image{max-height:none}}
</style></head><body><main><header><p>115-MI｜微生物與免疫學總複習</p><h1>從病程看細菌，從小安理解免疫</h1><p class="lead">教師檢視用截圖集。切換教材、尺寸與字型，逐張看實驗室狀態與知識節點；圖片區可捲動，點選「開啟原尺寸」可看完整圖。</p><nav><a href="../public/materials/micro-bacteria-review-v1/index.html">開啟細菌互動 preview</a><a href="../public/materials/immuno-concepts-review-v1/index.html">開啟免疫互動 preview</a><a href="MICRO_IMMUNO_REVIEW_REPORT.md">交件報告</a></nav><p class="notice">截圖只存本機：docs/micro-immuno-review-screenshots/ 已排除版控；截圖集頁面須搭配本機檔案使用，repository／正式網站不提供截圖。教材內嵌教學圖照常保留。教師已核可兩份畫面（2026-10-11）；正式本機建置與教材登錄、22 題 Excel 追加及完整 check 已通過，尚未部署。此截圖集對應與正式輸出 SHA 相同的核可畫面。既有 kit 沒有深色主題；「系統深色偏好」截圖保留實際淺色版面，不代表已新增深色主題。</p></header><section class="controls" aria-label="截圖篩選"><label>教材<select id="subject"><option value="micro-bacteria-review">第一小時｜細菌</option><option value="immuno-concepts-review">第二小時｜免疫</option></select></label><label>寬度<select id="width"><option value="390">390｜手機</option><option value="1280">1280｜桌機</option></select></label><label>字型<select id="font"><option value="system">system-ui</option><option value="noto">Noto Sans CJK TC</option><option value="fallback">Arial／sans-serif（fallback）</option></select></label><label>內容<select id="kind"><option value="all">實驗室＋知識節點</option><option value="lab">實驗室</option><option value="node">知識節點</option><option value="page">完整頁面／色系／減少動態</option></select></label></section><p class="status" id="status" aria-live="polite"></p><section id="grid" aria-label="教材截圖"></section><footer>2026-10-11｜<a href="micro-immuno-review/verification-results.json">完整驗證原始結果</a> · <a href="micro-immuno-review/figure-metadata.json">圖片與錨點座標</a></footer></main><script>'''
script='''
const data=DATA;
const $=id=>document.getElementById(id),subject=$('subject'),width=$('width'),font=$('font'),kind=$('kind');
const labels={unstained:'未染色','crystal-violet':'結晶紫',iodine:'碘液',decolorize:'酒精脫色',safranin:'番紅',primary:'初次免疫反應',secondary:'再次免疫反應'};
function render(){const items=data.filter(x=>x.slug===subject.value&&x.width===Number(width.value)&&x.font===font.value&&(kind.value==='all'?x.kind!=='page':x.kind===kind.value));$('grid').replaceChildren();$('status').textContent=`${subject.options[subject.selectedIndex].text} · ${width.value}px · ${font.options[font.selectedIndex].text} · ${items.length} 張`;for(const x of items){const card=document.createElement('article');if(x.width===390)card.className='mobile';const cap=document.createElement('div');cap.className='cap';const h=document.createElement('h2');h.textContent=x.kind==='lab'?'實驗室｜'+(labels[x.id]||x.id):x.title;cap.append(h);const meta=document.createElement('small');meta.textContent=x.width+'px · '+(x.font==='noto'?'Noto Sans CJK TC':x.font==='fallback'?'Arial／sans-serif':'system-ui');cap.append(meta);const wrap=document.createElement('div');wrap.className='image';const im=new Image();im.src='micro-immuno-review-screenshots/'+x.file;im.alt=h.textContent;im.loading='lazy';wrap.append(im);const tools=document.createElement('div');tools.className='tools';const a=document.createElement('a');a.href=im.src;a.target='_blank';a.rel='noopener';a.textContent='開啟原尺寸';tools.append(a);card.append(cap,wrap,tools);$('grid').append(card);}if(!items.length)$('status').textContent+='。完整頁面截圖請選 system-ui。';history.replaceState(null,'','#'+subject.value);}
if(location.hash.includes('immuno-concepts-review'))subject.value='immuno-concepts-review';[subject,width,font,kind].forEach(el=>el.addEventListener('change',render));render();
'''.replace('DATA',json.dumps(items,ensure_ascii=False))
(root/'docs/micro-immuno-review-preview.html').write_text(head+script+'</script></body></html>')
print('gallery entries',len(items))
